for fn in sorted(glob.glob(os.path.join(SRC, "shlokas_*.json"))):
    with open(fn, encoding="utf-8") as f:
        data = json.load(f)
    for item in data:
        n = item["num"]
        if n in QUOTE_UPGRADES:
            old_s, new_s, old_g, new_g = QUOTE_UPGRADES[n]
            if old_s in item["vritti_sa"]:
                item["vritti_sa"] = item["vritti_sa"].replace(old_s, new_s)
            if old_g in item["vritti_gu"]:
                item["vritti_gu"] = item["vritti_gu"].replace(old_g, new_g)
        if n in INNER_STATE_UPGRADES:
            sa_add, gu_add = INNER_STATE_UPGRADES[n]
            if sa_add not in item["vritti_sa"]:
                item["vritti_sa"] = item["vritti_sa"] + "\n\n" + sa_add
            if gu_add not in item["vritti_gu"]:
                item["vritti_gu"] = item["vritti_gu"] + "\n\n" + gu_add
    with open(fn, "w", encoding="utf-8") as f:
        json.dump(data, f, ensure_ascii=False, indent=2)
print("Upgraded all 25 shlokas with unique references, Alankaras, Prasa, and Devotee Inner States!")
